import {kartRace,bindKartRace} from './kart-race.js?v=20261106d';
import {greenhouse,bindGreenhouse} from './products-investigation.js?v=20261106d';
import {createCatchMusic} from './catch-music.js?v=20261106d';
import {icon,title,next,state,complete,escapeHTML,save} from './app.js?v=20261106d';
const $=s=>document.querySelector(s);
const collectSprite=(kind,label)=>`<span class="collect-sprite sprite-${kind}" role="img" aria-label="${label}"></span>`;
const needs=[['sun','Sunlight','Energy from the Sun'],['drop','Water','Absorbed through roots'],['wind','Carbon dioxide','Gas in the air that enters leaves'],['leaf','Chlorophyll','Green substance in plants that absorbs sunlight']];
let dispose=()=>{};
export function cleanupChapters(){dispose();dispose=()=>{}}
const heading=(id,h,p)=>title(id,h,p);
const feedback=()=>'<div id="chapter-feedback" class="chapter-feedback" role="status" aria-live="polite"></div>';
function induction(){return heading('induction','Meet Sprout & Beep!','Watch our short cartoon before we begin. How does a plant get its food?')+`<section class="induction-video"><div class="lesson-video"><button id="play-leaf-video" class="garden-video-cover" aria-label="Play Sprout and Beep’s photosynthesis cartoon"><img src="assets/photosynthesis-video-thumbnail.webp" alt="Sprout and Beep’s photosynthesis cartoon" width="2560" height="1440"><span class="video-play">${icon('play')} Watch Sprout & Beep</span></button></div><div class="lesson-video-note"><p>Watch the video, then share one thing you noticed with a partner. We’ll explore the science one chapter at a time.</p><a href="https://youtu.be/DJnnWQehI50" target="_blank" rel="noopener noreferrer">Open video on YouTube</a></div><p class="caption">This video was generated using Generative AI.</p><div class="induction-ready"><h2>What did you notice?</h2><p>How do you think Sprout gets its food? Share your first idea. You can change your mind as we learn!</p></div></section>`+next('induction','Chapter 1: the meaning')}
function meaning(){return heading('meaning','Plants have a food-making secret.','Chapter 1 · What does photosynthesis mean?')+`<section class="chapter-scene meaning-scene"><div class="chapter-character cast cast-sprout" aria-hidden="true"></div><div class="chapter-speech"><h2>“I make my own food!”</h2><p>Animals move to find food. Plants make their own food through <strong>photosynthesis</strong>.</p><div id="meaning-reveal"><p class="meaning-definition">Photosynthesis is a process where plants make their own food.</p><p>Your turn: say what photosynthesis means, then try the word game.</p></div></div></section><p class="caption">Science Year 4 · printed page 76.</p>`+next('meaning','Play Build the Meaning',true)}
function meaningGame(){return heading('meaning-game','Give Sprout the right words!','Chapter 1 game · Build the meaning of photosynthesis, one piece at a time.')+`<section class="chapter-scene word-scene"><div class="word-host">${icon('sprout')}<h2>Photosynthesis is…</h2></div><div id="word-slots" class="word-slots" aria-label="Your sentence">Pick the first word piece below.</div><div class="word-pieces">${['their own food.','a process','make','where plants'].map(t=>`<button class="word-piece" data-word="${t}">${t}</button>`).join('')}</div>${feedback()}<button id="word-reset" class="text-btn">${icon('arrow')} Build it again</button></section><p class="caption">This game was developed with assistance from Generative AI.</p>`+next('meaning-game','Chapter 2: the four needs',true)}
function needsGame(){return heading('needs-game','Collect & Avoid','Chapter 2 game · Move Sprout with the left and right arrow keys or A and D. Collect the four photosynthesis need symbols and dodge the distractions!')+`<section class="catch-game"><div class="catch-hud"><strong id="catch-score">0 points</strong><span id="catch-found">0 / 4 needs found</span><span id="catch-lives" class="catch-lives" role="status" aria-label="3 hearts remaining">♥ ♥ ♥</span><div class="catch-tools"><button id="catch-music" class="text-btn" aria-pressed="false">Mute music</button><button id="catch-pause" class="text-btn" disabled>Pause</button><button id="catch-fullscreen" class="icon-btn" aria-label="Enter fullscreen" title="Enter fullscreen" aria-pressed="false"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/></svg></button></div></div><div class="catch-field" id="catch-field" tabindex="0" role="region" aria-label="Collect and avoid game. Use the left and right arrow keys or A and D to move Sprout."><div class="catch-start" id="catch-overlay"><h2>Ready, little leaf catcher?</h2><p>Catch sunlight, water, carbon dioxide and chlorophyll leaves. Avoid toys and snacks! Miss a need and you lose a heart.</p><button id="catch-start" class="btn yellow">${icon('play')} Let’s collect!</button></div><div id="falling-items"></div><div id="catch-sprout" class="catch-sprout"><span class="cast cast-sprout"></span><span>SPROUT</span></div></div><div class="catch-controls"><p>Move Sprout: <kbd>←</kbd> / <kbd>→</kbd> or <kbd>A</kbd> / <kbd>D</kbd></p></div><div class="need-stamps">${needs.map((n,i)=>`<span data-stamp="${i}">${collectSprite(n[0],n[1])} ${n[1]}</span>`).join('')}</div><p class="caption">The molecule represents carbon dioxide. The green leaf represents chlorophyll. Chlorophyll is already inside leaves; plants do not catch it from the sky. Find all four needs to finish. You have three hearts; each missed need costs one heart.</p>${feedback()}<button id="catch-calm" class="text-btn">Use calm mode: choose what Sprout needs</button><div id="calm-choices" hidden></div></section><p class="caption">This game was developed with assistance from Generative AI.</p>`+next('needs-game','Chapter 3: the products',true)}
function products(){return heading('products','What have these plants made?','Chapter 3 · A greenhouse, two plants, and something to uncover.')+greenhouse(icon)+next('products','Race the Canopy Kart Cup',true)}
function productGame(){return heading('products-game','Canopy Kart Cup','Chapter 3 game · Take the corners. Chase your rivals. Race for the finish.')+kartRace()+'<p class="caption">This game was developed with assistance from Generative AI.</p>'+next('products-game','Review my discoveries',true)}
function recap(){return `<div class="page-heading"><h1>My photosynthesis discoveries</h1><p>Three chapters, one food-making secret.</p></div><section class="recap-sheet"><h2>What can you tell a partner?</h2><ol><li><strong>Meaning</strong><p>Photosynthesis is a process where plants make their own food.</p></li><li><strong>Four needs</strong><p>Sunlight, water, carbon dioxide and chlorophyll. Can you name at least two?</p></li><li><strong>Two products</strong><p>Starch and oxygen. Can you name at least one?</p></li></ol><p>You have reached the end of the lesson. Explain the three ideas in your own words. Your teacher can use your game choices and explanation to review your learning.</p><label for="chapter-reflection">My discovery in my own words</label><textarea id="chapter-reflection" rows="3" maxlength="600">${escapeHTML(state.journal)}</textarea><button id="chapter-save" class="btn">Save my note</button><button id="chapter-spoken" class="text-btn">I shared my discoveries aloud</button>${feedback()}<div class="actions"><a class="btn yellow" href="#grove">Play Nico’s forest · just for fun ${icon('game')}</a><a href="#map">Revisit my chapters</a></div></section>`}
function teacher(){return `<div class="page-heading"><h1>Teacher’s chapter guide</h1><p>Year 4 Science · Photosynthesis · LS 4.2.1, 4.2.2 and 4.2.3.</p></div><section class="recap-sheet"><h2>Learning objectives and success criteria</h2><ol><li><strong>State the meaning of photosynthesis.</strong><p>Build the Meaning: arrange the definition correctly, read the feedback and try again.</p></li><li><strong>Name at least two needs for photosynthesis.</strong><p>The leaf model introduces water, carbon dioxide, sunlight and chlorophyll. Collect & Avoid checks recognition of all four symbols; a calm selection mode is available. Chlorophyll is already inside the plant.</p></li><li><strong>Identify at least one product of photosynthesis from media.</strong><p>The greenhouse connects plant food to glucose stored as starch and illustrates oxygen release. Canopy Kart Cup checks choices between needs and products, with explanations and replay.</p></li></ol><p>Source: Science Year 4, printed pages 76–78. Games provide formative e-assessment. Observe choices, feedback and oral or written explanations; finishing a game alone is not an official performance level.</p><h2>A 20-minute lesson</h2><p>Video and initial discussion (2 min) → meaning (1) → sentence game (2) → four-needs model (3) → Collect & Avoid (3) → greenhouse (4) → Kart Cup (3) → discoveries and reflection (2). Nico’s forest is optional play after the lesson.</p><h2>Gagné and TPACK</h2><p>The cartoon gains attention and the opening question recalls prior ideas. The goals set expectations. Three chapters present content in small steps; the diagrams and prompts guide learning. Each game elicits a response, gives feedback and permits retry. The final journal supports recall and transfer. Teachers can ask pupils to explain their answers without the notes.</p><p>TPACK connects photosynthesis content, guided observation and formative assessment with diagrams, animation, sound and games. Each medium serves a specific learning goal.</p><h2>Access and classroom use</h2><p>Offer partner talk, keyboard or touch controls, larger text, reduced movement and calm mode. The printable trail is the alternative when internet access is limited. Browser progress stays on this device. Use a nickname and avoid personal details in reflections.</p><a class="btn" href="#map">Open the chapter trail</a></section>`}
export function renderChapter(route){return ({induction,meaning,'meaning-game':meaningGame,'needs-game':needsGame,products,'products-game':productGame,finish:recap,journal:recap,teacher}[route])()}
export function bindChapter(route){
 if(route==='induction'){$('#play-leaf-video').onclick=()=>{$('.lesson-video').innerHTML='<iframe src="https://www.youtube-nocookie.com/embed/DJnnWQehI50?autoplay=1&rel=0&playsinline=1" title="Sprout and Beep photosynthesis cartoon" allow="autoplay; accelerometer; encrypted-media; gyroscope; picture-in-picture; fullscreen" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>'};$('.lesson-nav .btn').addEventListener('click',()=>complete('induction'))}

 if(route==='meaning'){complete('meaning')}
 if(route==='meaning-game'){const answer=['a process','where plants','make','their own food.'];let words=[];document.querySelectorAll('[data-word]').forEach(b=>b.onclick=()=>{if(b.dataset.word!==answer[words.length]){$('#chapter-feedback').textContent='Try another piece. Think: a process… who makes what?';return}words.push(b.dataset.word);b.disabled=true;$('#word-slots').textContent=words.join(' ');$('#chapter-feedback').textContent=words.length===4?'You built it! Photosynthesis is a process where plants make their own food.':'That fits! Choose the next piece.';if(words.length===4)complete('meaning-game')});$('#word-reset').onclick=()=>{words=[];document.querySelectorAll('[data-word]').forEach(b=>b.disabled=false);$('#word-slots').textContent='Pick the first word piece below.';$('#chapter-feedback').textContent='';document.querySelector('[data-next-for="meaning-game"]').setAttribute('aria-disabled','true')}}
 if(route==='needs-game')bindCatch();
 if(route==='products')dispose=bindGreenhouse(()=>complete('products'));
 if(route==='products-game')dispose=bindKartRace(()=>complete('products-game'));
 if(route==='finish'||route==='journal'){$('#chapter-save').onclick=()=>{const note=$('#chapter-reflection').value.trim();if(!note){$('#chapter-feedback').textContent='Write one discovery, or share it aloud and choose the button below.';return}state.journal=note;save();complete('journal');$('#chapter-feedback').textContent='Your discovery note is saved. Your lesson is complete!'};$('#chapter-spoken').onclick=()=>{complete('journal');$('#chapter-feedback').textContent='Thank you for sharing your discoveries. Your lesson is complete!'}}
}
function bindCatch(){
 const field=$('#catch-field'),overlay=$('#catch-overlay'),holder=$('#falling-items'),sprout=$('#catch-sprout');let x=50,points=0,lives=3,found=new Set(),items=[],running=false,paused=false,question=false,ended=false,raf=0,last=0,spawn=0,count=0,keys=new Set(),calm=false;
 const game=field.closest('.catch-game'),fullscreenButton=$('#catch-fullscreen');
 const music=createCatchMusic(),musicButton=$('#catch-music');let musicMuted=!!state.settings.catchMusicMuted;
 const updateMusic=()=>{music.setPlaying(running&&!paused&&!question&&!ended&&!calm&&!document.hidden&&!musicMuted);const label=musicMuted?'Play music':'Mute music';if(musicButton.textContent!==label)musicButton.textContent=label;musicButton.setAttribute('aria-pressed',String(musicMuted));musicButton.setAttribute('aria-label',musicMuted?'Unmute game music':'Mute game music')};
 musicButton.onclick=()=>{musicMuted=!musicMuted;state.settings.catchMusicMuted=musicMuted;save();if(!musicMuted)music.unlock();updateMusic()};updateMusic();
 const updateFullscreen=()=>{const active=document.fullscreenElement===game||game.classList.contains('catch-expanded');fullscreenButton.setAttribute('aria-pressed',String(active));fullscreenButton.setAttribute('aria-label',active?'Exit fullscreen':'Enter fullscreen');fullscreenButton.title=active?'Exit fullscreen':'Enter fullscreen';fullscreenButton.querySelector('path').setAttribute('d',active?'M3 8h5V3m13 5h-5V3M8 21v-5H3m13 5v-5h5':'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5');keys.clear()};
 const leaveExpanded=()=>{game.classList.remove('catch-expanded');document.body.classList.remove('catch-has-fullscreen');updateFullscreen()};
 fullscreenButton.onclick=async()=>{if(document.fullscreenElement===game){await document.exitFullscreen();return}if(game.classList.contains('catch-expanded')){leaveExpanded();return}try{if(!game.requestFullscreen)throw new Error('No native fullscreen');await game.requestFullscreen()}catch{game.classList.add('catch-expanded');document.body.classList.add('catch-has-fullscreen')}updateFullscreen()};
 const escapeFullscreen=e=>{if(e.key==='Escape'&&game.classList.contains('catch-expanded')){leaveExpanded();fullscreenButton.focus()}};
 document.addEventListener('fullscreenchange',updateFullscreen);document.addEventListener('keydown',escapeFullscreen);
 // Compare the actual on-screen silhouettes, including Sprout's leaf tips.
 // The molecule is flatter than the other sprites, so omit its transparent margins.
 function touching(item){const a=item.el.getBoundingClientRect(),b=sprout.querySelector('.cast').getBoundingClientRect();const top=item.good&&item.n===2?.29:.06,bottom=item.good&&item.n===2?.68:.94;return a.left+a.width*.06<=b.right&&a.right-a.width*.06>=b.left&&a.top+a.height*top<=b.bottom&&a.top+a.height*bottom>=b.top}
 const distractions=[['game','Toy robot'],['star','Sweet'],['flask','Garden bucket'],['apple','Apple']];
 const update=()=>{$('#catch-score').textContent=`${points} points`;$('#catch-found').textContent=`${found.size} / 4 needs found`;const hearts=$('#catch-lives');hearts.textContent=Array.from({length:3},(_,i)=>i<lives?'♥':'♡').join(' ');hearts.setAttribute('aria-label',`${lives} ${lives===1?'heart':'hearts'} remaining`);document.querySelectorAll('[data-stamp]').forEach(b=>b.classList.toggle('collected',found.has(+b.dataset.stamp)))};
 function replay(){points=0;lives=3;found.clear();count=0;ended=false;calm=false;keys.clear();x=50;sprout.style.left='50%';$('#calm-choices').hidden=true;items.forEach(i=>i.el.remove());items=[];update();start()}
 function finishGame(won){ended=true;running=false;question=false;updateMusic();overlay.hidden=false;overlay.innerHTML=won?'<h2>All four needs collected!</h2><p>Sunlight, water, carbon dioxide and chlorophyll. Say at least two without looking!</p><button id="catch-replay" class="btn yellow">Play again</button>':'<h2>Game over</h2><p>All three hearts are gone. Try collecting the needs again!</p><button id="catch-replay" class="btn yellow">Try again</button>';$('#catch-replay').onclick=replay;$('#catch-pause').disabled=true;if(won)complete('needs-game')}
 function win(){finishGame(true)}
 function collect(i){found.add(i);points+=10;update();$('#chapter-feedback').textContent=`${needs[i][1]}: ${needs[i][2]}.`;if(found.size===4)win()}
 function bump(){question=true;$('#catch-pause').disabled=true;const rescue=[['Which need is absorbed through roots?',1,'Roots absorb water.'],['Which need supplies energy from the Sun?',0,'Sunlight supplies energy.'],['Which gas enters leaves from the air?',2,'Carbon dioxide enters leaves from the air.'],['Which green substance absorbs sunlight?',3,'Chlorophyll is the green substance that absorbs sunlight.']][count%4];const needsOnly=count%2===0;const pool=needs.map((n,i)=>({label:n[1],glyph:n[0],correct:i===rescue[1]}));const choices=needsOnly?pool:(()=>{const mixed=[pool[rescue[1]],{label:'A toy robot',glyph:'game',correct:false},{label:'An apple',glyph:'apple',correct:false},pool[(rescue[1]+1)%4]];return mixed.slice(0,3)})();choices.sort(()=>Math.random()-.5);overlay.hidden=false;overlay.innerHTML=`<h2>A little leaf rescue!</h2><p>${rescue[0]}</p><div class="rescue-choices">${choices.map(({label,glyph,correct})=>`<button data-rescue="${correct?1:0}">${collectSprite(glyph,label)}<span>${label}</span></button>`).join('')}</div><p id="rescue-feedback" role="status">Choose the best answer.</p>`;overlay.querySelectorAll('[data-rescue]').forEach(b=>b.onclick=()=>{if(+b.dataset.rescue<0){$('#rescue-feedback').textContent=`That is a distraction. ${rescue[2]} Try again!`;return}if(+b.dataset.rescue===0){$('#rescue-feedback').textContent='That is a different plant need. Read the question again.';return}question=false;$('#catch-pause').disabled=false;overlay.hidden=true;$('#chapter-feedback').textContent=rescue[2]+' Back to collecting.';last=performance.now();field.focus({preventScroll:true})})}
 function add(){const good=count%3!==2;const n=count%3===2?Math.floor(count/3)%3:Math.floor(count/3)%4;const data=good?needs[n]:distractions[n];count++;const el=document.createElement('div');el.className='falling-token';el.innerHTML=collectSprite(data[0],data[1])+(data[0]==='wind'?'<span class="object-label">CO₂</span>':data[0]==='leaf'?'<span class="object-label">Chlorophyll</span>':'');const item={el,x:12+Math.random()*76,y:-12,good,n};holder.append(el);items.push(item)}
 function tick(now){const dt=Math.min((now-last)/1000,.05);last=now;updateMusic();if(running&&!paused&&!question&&!ended&&!calm&&!document.hidden){if(keys.has('ArrowLeft')||keys.has('a'))x-=dt*60;if(keys.has('ArrowRight')||keys.has('d'))x+=dt*60;x=Math.max(9,Math.min(91,x));sprout.style.left=x+'%';spawn+=dt;if(spawn>.65){spawn=0;add()}for(const i of [...items]){i.y+=dt*34;i.el.style.left=i.x+'%';i.el.style.top=i.y+'%';if(touching(i)){i.el.remove();items=items.filter(j=>j!==i);if(i.good)collect(i.n);else bump();if(question||ended)break}else if(i.y>100){i.el.remove();items=items.filter(j=>j!==i);if(i.good){lives--;update();$('#chapter-feedback').textContent=`Missed ${needs[i.n][1]}. ${lives} ${lives===1?'heart':'hearts'} left.`;if(lives===0){finishGame(false);break}}}}}raf=requestAnimationFrame(tick)}
 function start(){music.unlock();spawn=.65;running=true;paused=false;question=false;$('#catch-pause').disabled=false;overlay.hidden=true;$('#catch-pause').disabled=false;$('#catch-pause').textContent='Pause';last=performance.now();field.scrollIntoView({block:'center',behavior:'instant'});field.focus({preventScroll:true});if(!raf)raf=requestAnimationFrame(tick)}
 $('#catch-start').onclick=start;
 $('#catch-pause').onclick=()=>{paused=!paused;$('#catch-pause').textContent=paused?'Resume':'Pause';overlay.hidden=!paused;overlay.innerHTML=paused?'<h2>Taking a leaf break.</h2><p>Press Resume when you’re ready.</p>':'';keys.clear()};
 const keydown=e=>{const key=e.key.length===1?e.key.toLowerCase():e.key;if(['ArrowLeft','ArrowRight','a','d'].includes(key)&&!e.target.closest('input,textarea')){e.preventDefault();keys.add(key)}};const keyup=e=>keys.delete(e.key.length===1?e.key.toLowerCase():e.key);document.addEventListener('keydown',keydown);document.addEventListener('keyup',keyup);
 $('#catch-calm').onclick=()=>{calm=true;running=false;overlay.hidden=true;holder.innerHTML='';items=[];$('#catch-pause').disabled=true;$('#calm-choices').hidden=false;$('#calm-choices').innerHTML=`<p>Tap the four needs. Leave the distractions behind.</p><div class="calm-tokens">${[...needs.map((n,i)=>[n[0],n[1],i]),...distractions.map(n=>[n[0],n[1],-1])].sort((a,b)=>a[1].localeCompare(b[1])).map(n=>`<button data-calm="${n[2]}">${collectSprite(n[0],n[1])}<span>${n[1]}</span></button>`).join('')}</div>`;document.querySelectorAll('[data-calm]').forEach(b=>b.onclick=()=>{if(+b.dataset.calm<0){$('#chapter-feedback').textContent='That is a distraction. Look for a photosynthesis need.';return}b.disabled=true;collect(+b.dataset.calm)})};
 const blur=()=>{keys.clear();if(running&&!paused&&!question&&!ended)$('#catch-pause').click()};window.addEventListener('blur',blur);
 dispose=()=>{music.dispose();document.removeEventListener('fullscreenchange',updateFullscreen);document.removeEventListener('keydown',escapeFullscreen);if(document.fullscreenElement===game)document.exitFullscreen().catch(()=>{});leaveExpanded();cancelAnimationFrame(raf);document.removeEventListener('keydown',keydown);document.removeEventListener('keyup',keyup);window.removeEventListener('blur',blur)};
}
